tasks.starter_code:
// 금액에 적용할 할인 규칙의 약속이에요.
interface Rate {
    int apply(int won);
}

class Half implements Rate {
    public int apply(int won) {
        return won / 2;
    }
}

class Minus implements Rate {
    public int apply(int won) {
        return won - 1000;
    }
}

class Main {
    public static void main(String[] args) {
        int won = 8000;
        Rate[] rules = { new Half(), new Minus() };
        // 규칙을 배열 순서대로 하나씩 적용해요.
        for (Rate r : rules) {
            won = rules[0].apply(won);
        }
        System.out.println(won);
    }
}

