tasks.starter_code:
interface Rate {
    int apply(int won);
}

class Main {
    // 규칙을 적용하다 잘못된 금액이면 0을 돌려줘요.
    static int safe(Rate r, int won) {
        try {
            return r.apply(won);
        } catch (IllegalArgumentException e) {
            return 0;
        }
    }

    public static void main(String[] args) {
        int won = 700;
        // 1000원보다 적으면 뺄 수 없어 예외를 던져요.
        Rate minus = w -> {
            if (w < 1000) {
                throw new IllegalArgumentException("금액 부족");
            }
            return w - 1000;
        };
        System.out.println("규칙 준비 끝");
        // 이 줄을 고쳐 safe를 거쳐 규칙을 적용하세요.
        System.out.println(minus.apply(won));
    }
}

